"""Single mount-pitch candidate from actual B3 rest mesh;geometry ONLY."""
import argparse,json,xml.etree.ElementTree as ET
from pathlib import Path
import numpy as np
import trimesh
from scipy.spatial.transform import Rotation
from analyse import BASE,sha
def main():
 p=argparse.ArgumentParser();p.add_argument('--tag',required=True);a=p.parse_args();out=BASE/'results'/a.tag;out.mkdir(exist_ok=False);src=BASE/'results/b3_railback_grasp1001298';root=ET.parse(src/'scene.scn').getroot();cfg=json.loads((src/'config.json').read_text());mesh=json.loads((src/'mesh.json').read_text());local=np.array(mesh['local_positions_mm']);records=[];centre=np.array(cfg['simulation']['sphere_center_mm'])/1000;R=cfg['simulation']['sphere_radius_mm']/1000;contact_gap=cfg['simulation']['contact_distance_mm']/1000;tet=np.array(mesh['tetrahedra'])
 for pitch in (0.,14.):
  for i,angle in enumerate((0.,120.,240.)):
   q0=np.fromstring(root.find(f"./Node[@name='finger{i}']/MechanicalObject").get('position'),sep=' ').reshape(-1,3);theta=np.deg2rad(angle);origin=.05*np.array([np.cos(theta),np.sin(theta),0.]);axis=np.array([-np.sin(theta),np.cos(theta),0.]);rot=Rotation.from_rotvec(np.deg2rad(pitch)*axis);q=origin+rot.apply(q0-origin);skin=root.find(f"./Node[@name='finger{i}']/Node[@name='skinCollision']");ids=np.fromstring(skin.find('SubsetMapping').get('indices'),sep=' ',dtype=int);tri=np.fromstring(skin.find('MeshTopology').get('triangles'),sep=' ',dtype=int).reshape(-1,3);faces=ids[tri];near=trimesh.triangles.closest_point(q[faces],np.repeat(centre[None],len(faces),axis=0));gaps=np.linalg.norm(near-centre,axis=1)-R;k=int(np.argmin(gaps));w=trimesh.triangles.points_to_barycentric(q[faces[k]][None],near[k][None])[0];D=np.linalg.det((q[tet[:,1:]]-q[tet[:,0,None]]).transpose(0,2,1));D0=np.linalg.det((q0[tet[:,1:]]-q0[tet[:,0,None]]).transpose(0,2,1));ratio=D/D0;assert np.all(ratio>0)
   records.append(dict(additional_pitch_deg=pitch,total_mount_pitch_deg=cfg['palm']['root_angle_deg']+pitch,finger=i,minimum_initial_skin_sphere_gap_m=float(gaps[k]),nearest_material_reference_mm=(w@local[faces[k]]).tolist(),minimum_reference_volume_ratio=float(ratio.min()),max_reference_volume_ratio_error=float(abs(ratio-1).max()),skin_contact_margin_pass=bool(gaps[k]>=contact_gap)))
   if pitch:trimesh.Trimesh(q[ids],tri,process=False).export(out/f'skin_collision_finger{i}.stl');(out/f'candidate_finger{i}_q0.json').write_text(json.dumps(q.tolist()))
 d=dict(status='PASS_SKIN_ONLY_INITIAL_GEOMETRY' if all(r['skin_contact_margin_pass'] for r in records) else 'REJECT_SKIN_INITIAL_GEOMETRY',records=records,design_change='Rigid initialmountpitch0→14deg about localtangent;100mm manufacturedprecurve40 retained,radius50mm/layout120 unchanged. Not prescribed dynamic bending.',sphere_radius_m=R,object_initial_centre_m=centre.tolist(),required_contact_margin_m=contact_gap,hardware_wire_clearance=None,interfinger_swept_clearance=None,Native_scene='NOT CREATED_UNTIL_ALL_INITIAL_PARTS_TRANSFORMED_AND_CHECKED',physical_validation='NOT QUALIFIED',scope='Initial Skin triangle/sphere and rigidly rotated FEM volume only. Exported STL is collisiongeometry,not manufactured solid/STEP/assembly. Guide/anchor/cable/frame transforms and hardware gaps remain REQUIRED;no collision disabled or dynamicgrasp performed.',input_hashes={f:sha(src/f) for f in ('scene.scn','mesh.json','config.json')});(out/'producer.py').write_bytes(Path(__file__).read_bytes());(out/'summary.json').write_text(json.dumps(d,indent=2));print(json.dumps(d))
if __name__=='__main__':main()
